import (
	"errors"
	"fmt"

	"github.com/sony/gobreaker"
)

func main() {
	st := gobreaker.Settings{
		Name:        "payments",
		MaxRequests: 1, // probes allowed in Half-Open
		ReadyToTrip: func(c gobreaker.Counts) bool {
			// Trip after 3 consecutive failures (simple demo policy).
			return c.ConsecutiveFailures >= 3
		},
		OnStateChange: func(name string, from, to gobreaker.State) {
			fmt.Printf("breaker %q: %v -> %v\n", name, from, to)
		},
	}
	cb := gobreaker.NewCircuitBreaker(st)

	call := func() (any, error) {
		fmt.Println("calling dependency")
		return nil, errors.New("dependency down")
	}

	for i := 1; i <= 4; i++ {
		_, err := cb.Execute(call)
		fmt.Printf("attempt %d: %v\n", i, err)
	}
}

