	for attempt := 0; attempt < 4; attempt++ {
		// Exponential growth: the ceiling doubles each attempt.
		ceil := time.Duration(float64(base) * math.Pow(2, float64(attempt)))
		// Real code sleeps a random duration in [ceil/2, ceil) so clients
		// don't synchronize into a thundering herd (full jitter variant).
		fmt.Printf("attempt %d ceil=%v jitter=[%v,%v)\n", attempt, ceil, ceil/2, ceil)
	}
