package solution

import (
	"errors"
	"testing"
	"time"
)

func TestBreaker(t *testing.T) {
	// Controllable clock: advance it manually, no real sleeping.
	now := time.Unix(0, 0)
	clock := func() time.Time { return now }

	b := NewBreaker(3, 5*time.Second, clock)
	fail := func() error { return errors.New("boom") }
	ok := func() error { return nil }

	// 3 consecutive failures should trip the breaker open.
	for i := 0; i < 3; i++ {
		if err := b.Execute(fail); err == nil {
			t.Fatalf("failure %d: want error", i)
		}
	}
	// Now Open: calls fail fast with ErrOpen without invoking fn.
	called := false
	if err := b.Execute(func() error { called = true; return nil }); err != ErrOpen {
		t.Fatalf("want ErrOpen while open, got %v", err)
	}
	if called {
		t.Fatal("fn must not run while breaker is open")
	}

	// Before cooldown elapses, still open.
	now = now.Add(4 * time.Second)
	if err := b.Execute(ok); err != ErrOpen {
		t.Fatalf("want ErrOpen before cooldown, got %v", err)
	}

	// After cooldown, Half-Open admits one probe; success closes it.
	now = now.Add(2 * time.Second) // total 6s > 5s cooldown
	if err := b.Execute(ok); err != nil {
		t.Fatalf("half-open probe should run and succeed, got %v", err)
	}
	// Closed again: a single failure must not immediately re-trip.
	if err := b.Execute(fail); err == nil {
		t.Fatal("want underlying error")
	}
	if err := b.Execute(ok); err != nil {
		t.Fatalf("breaker should be closed and allow calls, got %v", err)
	}
}

