// callWithRetry adds a breaker, jittered exponential backoff, and ctx awareness.
func callWithRetry(ctx context.Context, cb *Breaker, r *rand.Rand, do func() error) error {
	const base = 50 * time.Millisecond
	var err error
	for attempt := 0; attempt < 5; attempt++ {
		// Breaker short-circuits instantly once open -> no retry storm.
		err = cb.Execute(do)
		if err == nil {
			return nil
		}
		if errors.Is(err, ErrOpen) {
			return err // dependency is known-down; stop hammering it
		}
		// Exponential backoff with full jitter, in [0, base*2^attempt).
		backoff := time.Duration(float64(base) * math.Pow(2, float64(attempt)))
		sleep := time.Duration(r.Int63n(int64(backoff) + 1))
		select {
		case <-time.After(sleep):
		case <-ctx.Done(): // deadline/cancel stops retries immediately
			return ctx.Err()
		}
	}
	return err
}

func WithBulkhead(limit int) func(ctx context.Context) (func(), error) {
	sem := make(chan struct{}, limit) // buffered channel = counting semaphore
	return func(ctx context.Context) (func(), error) {
		select {
		case sem <- struct{}{}: // acquired a slot
			var once sync.Once
			release := func() { once.Do(func() { <-sem }) } // idempotent release
			return release, nil
		case <-ctx.Done(): // full and the caller's deadline/cancel fired
			return nil, ctx.Err()
		}
	}
}
